//! One embedded literal escaped bang in EXT class identifiers only.
use kobo_web_document::{Limits,SupplyBudget,SnapshotState,HistoryState,InputState,FocusState,TargetState};
fn snap()->SnapshotState{SnapshotState{history:None,input:None,focus:None,target:None}}
fn run(c:&str,b:&str,l:&Limits,s:&SnapshotState)->kobo_web_document::style_tree::StyleTree{let h=format!("<!doctype html><style>{c}</style>{b}");kobo_web_document::parse_style_tree_with_state(h.as_bytes(),&[],l,None,SupplyBudget::CANONICAL,s)}
#[test] fn browser_color_rank9(){let h=include_str!("fixtures/embedded_class_bang_cascade.html");let t=kobo_web_document::parse_style_tree_with_state(h.as_bytes(),&[],&Limits::DEFAULT,None,SupplyBudget::CANONICAL,&snap());assert!(!t.unsupported&&!t.truncated);assert_eq!(t.nodes.iter().filter(|n|n.tag=="div").map(|n|n.style.color).collect::<Vec<_>>(),[0x0000ff,0xff0000,0x0000ff,0xff0000,0x0000ff,0x0000ff,0x0000ff,0x0000ff,0x0000ff]);}
#[test] fn state_families_target_autofocus_and_partial_loss(){let c=r".absent:has(.a\!x:where(:not(:focus))){color:red}";let b="<div><b class='a!x'></b></div>";let mut s=snap();assert!(run(c,b,&Limits::DEFAULT,&s).unsupported);s.history=Some(HistoryState::FreshNoHistory);s.input=Some(InputState::QuiescentCapture);assert!(run(c,b,&Limits::DEFAULT,&s).unsupported);s.focus=Some(FocusState::UnfocusedInitial);assert!(!run(c,b,&Limits::DEFAULT,&s).unsupported);assert!(run(c,"<div><b class='a!x' autofocus></b></div>",&Limits::DEFAULT,&s).unsupported);s.target=Some(TargetState::Fragment("tail".into()));let t=run(r".a\!x:target{color:red}","<div id=tail class='a!x'></div>",&Limits::DEFAULT,&s);assert!(!t.unsupported);assert_eq!(t.nodes.iter().find(|n|n.tag=="div").unwrap().style.color,0xff0000);for q in [r":where(.a\!x)",r":not(.a\!x)",r"div:has(.a\!x)"]{for l in [Limits{max_input_bytes:50,..Limits::DEFAULT},Limits{max_nodes:1,..Limits::DEFAULT},Limits{max_text_bytes:0,..Limits::DEFAULT}]{let t=run(&format!("{q}{{color:red}}"),"<div><b class='a!x'>text</b></div>",&l,&snap());assert!(t.unsupported||t.truncated);}}}
#[test] fn long_class_bytework_and_aggregate_global_work(){let b=format!("<div class='{}'></div>","a!y ".repeat(500));let t=run(r":not(.a\!x):not(.a\!x):not(.a\!x){color:red}",&b,&Limits::DEFAULT,&snap());assert!(t.truncated);assert!(t.diagnostics.count(kobo_web_document::style_diagnostics::RefusalReason::MatchWork)>0);let one=format!("<div class='{}'></div>","a ".repeat(100));let q=r":where(.a\!x){color:red}";assert!(!run(q,&one,&Limits::DEFAULT,&snap()).truncated);let t=run(&q.repeat(100),&one.repeat(200),&Limits::DEFAULT,&snap());assert!(t.truncated);assert!(t.diagnostics.count(kobo_web_document::style_diagnostics::RefusalReason::MatchWork)>0);assert_eq!(t.diagnostics.count(kobo_web_document::style_diagnostics::RefusalReason::DomNodes),0);}
#[test] fn default_and_other_identifier_isolation_attribute_loss(){let h=r"<!doctype html><style>.a\!x{color:red}</style><div class='a!x'></div>";let t=kobo_web_document::parse_style_tree(h.as_bytes(),&[],&Limits::DEFAULT);assert!(t.unsupported);for q in [r"#a\!x",r"a\!x",r"[a\!x]",r"[a=a\!x]",r":a\!x"]{assert!(run(&format!("{q}{{color:red}}"),"<div class='a!x'></div>",&Limits::DEFAULT,&snap()).unsupported);}let b=format!("<div {} class='a!x'></div>",(0..40).map(|i|format!("data-x{i}=a ")).collect::<String>());let t=run(r"div:has(.a\!x){color:red}",&b,&Limits::DEFAULT,&snap());assert!(t.diagnostics.dropped_attributes>0&&t.truncated,"retained diagnostic tree partial, no universal enrollment invalidation");assert!(!t.unsupported,"class-only enrollment unchanged, not silent complete page");}
#[test] #[ignore="measurement: EMBEDDED_CLASS_BANG_LINES original225 individual rows"] fn original225_public_inventory(){let text=std::fs::read_to_string(std::env::var("EMBEDDED_CLASS_BANG_LINES").unwrap()).unwrap();let mut total=0;for(i,l)in text.lines().enumerate(){total+=1;let class=l.strip_prefix('.').unwrap().replace(r"\!","!");let t=run(&format!("{l}{{color:red}}"),&format!("<div class='{class}'></div>"),&Limits::DEFAULT,&snap());let yes=!t.unsupported&&!t.truncated&&t.nodes.iter().find(|n|n.tag=="div").unwrap().style.color==0xff0000;println!("CLASS-BANG-PUBLIC line={} admitted_and_matched={} first={:?}",i+1,yes,t.diagnostics.first_reason());assert!(yes,"{l}");}assert_eq!(total,225);println!("CLASS-BANG-PUBLIC total={total} admitted_and_matched=225 refused=0");}
